                             <Clock size={10} /> {language === 'HI' ? 'जाँच जारी है' : 'WAITING APPROVAL'}
                          </span>
                       )}
                       {listing.status === 'APPROVED' && (
                          <span className="flex items-center gap-1 bg-green-500 text-white text-[10px] font-bold px-2 py-1 rounded-full shadow-lg">
                             <CheckCircle size={10} /> {language === 'HI' ? 'सत्यापित' : 'LIVE & APPROVED'}
                          </span>
                       )}
                       {listing.status === 'REJECTED' && (
                          <span className="flex items-center gap-1 bg-red-500 text-white text-[10px] font-bold px-2 py-1 rounded-full shadow-lg">
                             <XCircle size={10} /> {language === 'HI' ? 'अस्वीकृत' : 'REJECTED'}
                          </span>
                       )}
                    </div>

                    <div className="absolute bottom-2 left-2 bg-blue-600/90 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-1 rounded">
                      {listing.type}
                    </div>
                 </div>
                 <div className="p-4">
                    <div className="flex justify-between items-start mb-1">
                      <h4 className="font-bold text-gray-800">{listing.locality}</h4>
                      <span className="font-bold text-blue-600">₹{listing.rentPrice}</span>
                    </div>
                    <p className="text-xs text-gray-500 mb-4 line-clamp-1">{listing.address}</p>

                    <div className="flex items-center justify-between text-[10px] text-gray-400 border-t pt-2 mt-auto">
                       <span>
                          Status: 
                          <span className={`ml-1 font-bold ${
                             listing.status === 'APPROVED' ? 'text-green-600' : 
                             listing.status === 'PENDING' ? 'text-yellow-600' : 'text-red-600'
                          }`}>
                             {listing.status}
                          </span>
                       </span>
                       <span className="opacity-50">ID: {listing.id}</span>
                    </div>
                 </div>
              </div>
            ))
          ) : (
            <div className="col-span-full bg-white p-12 rounded-xl text-center border-dashed border-2 border-gray-300">
               <Home size={40} className="mx-auto text-gray-300 mb-2" />
               <p className="text-gray-500">You haven't listed any rooms yet.</p>
            </div>
          )}
        </div>

      </div>
    </div>
  );
};

export default OwnerDashboard;

import React, { useState } from 'react';
import { X, Mail, Lock, User, Key, CheckCircle, ArrowRight } from 'lucide-react';
import { Language, User as UserType } from '../types';
import { translations } from '../translations';

interface AuthModalProps {
  onClose: () => void;
  onLoginSuccess: (user: UserType) => void;
  language: Language;
}

type AuthStep = 'SIGNUP' | 'OTP' | 'LOGIN';

const AuthModal: React.FC<AuthModalProps> = ({ onClose, onLoginSuccess, language }) => {
  const [step, setStep] = useState<AuthStep>('LOGIN');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [isLoading, setIsLoading] = useState(false);

  const t = translations[language];

  const handleSignupSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    // Simulating sending OTP to Gmail
    setTimeout(() => {
      setIsLoading(false);
      setStep('OTP');
      alert(language === 'HI' ? `OTP आपके ईमेल ${email} पर भेज दिया गया है। (डेमो के लिए 123456 का उपयोग करें)` : `OTP sent to ${email}. (Use 123456 for demo)`);
    }, 1500);
  };

  const handleOtpChange = (index: number, value: string) => {
    if (value.length > 1) return;
    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);

    // Auto focus next input
    if (value && index < 5) {
      const nextInput = document.getElementById(`otp-${index + 1}`);
      nextInput?.focus();
    }
  };

  const handleVerifyOtp = () => {
    const enteredOtp = otp.join('');
    if (enteredOtp === '123456') {
      setIsLoading(true);
      setTimeout(() => {
        const newUser: UserType = {
          id: 'user_' + Date.now(),
          name: name || 'User',
          email: email,
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`
        };
        onLoginSuccess(newUser);
        onClose();
      }, 1000);
    } else {
      alert(language === 'HI' ? 'गलत OTP, कृपया 123456 डालें' : 'Incorrect OTP, please use 123456');
    }
  };

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setTimeout(() => {
      const mockUser: UserType = {
        id: 'user_123',
        name: 'Vinay Chandravanshi',
        email: email,
        avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Vinay'
      };
      onLoginSuccess(mockUser);
      onClose();
    }, 1000);
  };

  return (
    <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full overflow-hidden">
        {/* Header */}
        <div className="bg-orange-600 p-6 flex justify-between items-center text-white relative">
          <div>
            <h3 className="text-2xl font-black">
              {step === 'LOGIN' ? (language === 'HI' ? 'लॉगिन करें' : 'Login') : 
               step === 'SIGNUP' ? (language === 'HI' ? 'खाता बनाएं' : 'Create Account') :
               (language === 'HI' ? 'ईमेल सत्यापित करें' : 'Verify Email')}
            </h3>
            <p className="text-orange-100 text-xs font-medium mt-1">
              {step === 'OTP' ? `${language === 'HI' ? 'OTP भेजा गया:' : 'OTP Sent to:'} ${email}` : (language === 'HI' ? 'कवर्धा के सबसे बड़े रूम नेटवर्क से जुड़ें' : 'Join Kawardha\'s largest room network')}
            </p>
          </div>
          <button onClick={onClose} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="p-8">
          {step === 'LOGIN' && (
            <form onSubmit={handleLoginSubmit} className="space-y-5">
              <div className="relative">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1 block">Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="email" 
                    required
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 outline-none transition-all font-medium"
                    placeholder="example@gmail.com"
                  />
                </div>
              </div>
              <div className="relative">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1 block">Password</label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="password" 
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 outline-none transition-all font-medium"
                    placeholder="••••••••"
                  />
                </div>
              </div>
              <button 
                type="submit"
                disabled={isLoading}
                className="w-full bg-orange-600 text-white py-4 rounded-2xl font-black text-lg hover:bg-orange-700 transition-all shadow-xl shadow-orange-100 flex items-center justify-center gap-2"
              >
                {isLoading ? <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : (language === 'HI' ? 'लॉगिन' : 'Login')}
              </button>
              <p className="text-center text-sm text-slate-500">
                {language === 'HI' ? 'खाता नहीं है?' : "Don't have an account?"} {' '}
                <button type="button" onClick={() => setStep('SIGNUP')} className="text-orange-600 font-bold hover:underline">
                  {language === 'HI' ? 'साइनअप करें' : 'Sign up'}
                </button>
              </p>
            </form>
          )}

          {step === 'SIGNUP' && (
            <form onSubmit={handleSignupSubmit} className="space-y-4">
              <div className="relative">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1 block">Username</label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    required
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 outline-none transition-all font-medium"
                    placeholder="Full Name"
                  />
                </div>
              </div>
              <div className="relative">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1 block">Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="email" 
                    required
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 outline-none transition-all font-medium"
                    placeholder="your@gmail.com"
                  />
                </div>
              </div>
              <div className="relative">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1 block">Password</label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="password" 
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 outline-none transition-all font-medium"
                    placeholder="Create a password"
                  />
                </div>
              </div>
              <button 
                type="submit"
                disabled={isLoading}
                className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg hover:bg-slate-800 transition-all shadow-xl shadow-slate-100 flex items-center justify-center gap-2"
              >
                {isLoading ? <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : (language === 'HI' ? 'OTP भेजें' : 'Send OTP to Gmail')}
              </button>
              <button type="button" onClick={() => setStep('LOGIN')} className="w-full text-sm text-slate-400 font-bold hover:text-slate-600">
                {language === 'HI' ? 'वापस लॉगिन पर जाएं' : 'Back to Login'}
              </button>
            </form>
          )}

          {step === 'OTP' && (
            <div className="space-y-8 animate-fade-in">
              <div className="flex justify-between gap-2">
                {otp.map((digit, idx) => (
                  <input
                    key={idx}
                    id={`otp-${idx}`}
                    type="text"
                    maxLength={1}
                    value={digit}
                    onChange={(e) => handleOtpChange(idx, e.target.value)}
                    className="w-12 h-14 text-center text-2xl font-black border-2 border-slate-100 bg-slate-50 rounded-xl focus:border-orange-500 focus:bg-white outline-none transition-all"
                  />
                ))}
              </div>

              <div className="bg-blue-50 p-4 rounded-2xl border border-blue-100">
                <p className="text-xs text-blue-700 font-bold leading-relaxed flex items-center gap-2">
                  <Key size={16} /> {language === 'HI' ? 'हमने आपके ईमेल पर 6 अंकों का कोड भेजा है।' : 'We have sent a 6-digit code to your email.'}
                </p>
              </div>

              <button 
                onClick={handleVerifyOtp}
                disabled={isLoading || otp.some(d => !d)}
                className="w-full bg-orange-600 text-white py-4 rounded-2xl font-black text-lg hover:bg-orange-700 transition-all shadow-xl shadow-orange-100 flex items-center justify-center gap-2 disabled:opacity-50"
              >
                {isLoading ? <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : (language === 'HI' ? 'सत्यापित करें' : 'Verify & Continue')}
              </button>

              <button 
                type="button" 
                onClick={() => setStep('SIGNUP')} 
                className="w-full text-sm text-slate-400 font-bold hover:text-slate-600"
              >
                {language === 'HI' ? 'ईमेल बदलें' : 'Change Email'}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AuthModal;

import React, { useState, useMemo } from 'react';
import Header from './components/Header';
import Footer from './components/Footer';
import FilterBar from './components/FilterBar';
import ListingCard from './components/ListingCard';
import AIAssistant from './components/AIAssistant';
import SubscriptionGate from './components/SubscriptionGate';
import AdminListingForm from './components/AdminListingForm';
import AdminDashboard from './components/AdminDashboard';
import OwnerDashboard from './components/OwnerDashboard';
import LandingPage from './components/LandingPage';
import BookingModal from './components/BookingModal';
import AuthModal from './components/AuthModal';
import { MOCK_LISTINGS } from './constants';
import { FilterState, Listing, ViewState, Booking, Language, ListingStatus, User } from './types';
import { translations } from './translations';
import { SearchX } from 'lucide-react';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>('LANDING');
  const [language, setLanguage] = useState<Language>('HI');
  const [user, setUser] = useState<User | null>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const t = translations[language];

  const [listings, setListings] = useState<Listing[]>(MOCK_LISTINGS || []);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [filters, setFilters] = useState<FilterState>({
    maxPrice: 8000,
    roomType: 'ALL',
    locality: 'ALL'
  });

  const [isSubscribed, setIsSubscribed] = useState(false);
  const [isOwnerSubscribed, setIsOwnerSubscribed] = useState(false);
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingListing, setEditingListing] = useState<Listing | null>(null);
  const [bookingListing, setBookingListing] = useState<Listing | null>(null);

  const handleLoginSuccess = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('LANDING');
    setIsSubscribed(false);
    setIsOwnerSubscribed(false);
  };

  const handleAddListing = (newListing: Listing) => {
    const entry = { ...newListing, status: currentView === 'OWNER' ? 'PENDING' : 'APPROVED' };
    setListings(prev => [entry, ...prev]);
    setShowAddForm(false);
  };

  const handleUpdateListing = (updatedListing: Listing) => {
    setListings(prev => prev.map(l => l.id === updatedListing.id ? updatedListing : l));
    setEditingListing(null);
  };

  const handleUpdateListingStatus = (id: string, status: ListingStatus) => {
    setListings(prev => prev.map(l => l.id === id ? { ...l, status } : l));
  };

  const handleDeleteListing = (id: string) => {
    if (confirm(language === 'HI' ? 'क्या आप वाकई इस कमरे को हटाना चाहते हैं?' : 'Are you sure you want to delete this room?')) {
      setListings(prev => prev.filter(l => l.id !== id));
    }
  };

  const handleCreateBooking = (customerName: string, customerPhone: string) => {
    if (!bookingListing) return;
    const newBooking: Booking = {
      id: Date.now().toString(),
      listingId: bookingListing.id,
      customerName,
      customerPhone,
      status: 'PENDING',
      date: new Date().toISOString()
    };
    setBookings(prev => [newBooking, ...prev]);
    setBookingListing(null);
    alert(language === 'HI' ? 'बुकिंग अनुरोध भेज दिया गया है! एडमिन आपसे संपर्क करेंगे।' : 'Booking Request Sent! Admin will contact you.');
  };

  const handleUpdateBookingStatus = (id: string, status: 'APPROVED' | 'REJECTED') => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status } : b));
  };

  const filteredListings = useMemo(() => {
    if (!listings) return [];
    return listings.filter(listing => {
      if (listing.status !== 'APPROVED') return false;
      if (listing.rentPrice > filters.maxPrice) return false;
      if (filters.roomType !== 'ALL' && listing.type !== filters.roomType) return false;
      if (filters.locality !== 'ALL' && listing.locality !== filters.locality) return false;
      return true;
    });
  }, [filters, listings]);

  if (currentView === 'LANDING') {
    return (
      <>
        <LandingPage onNavigate={setCurrentView} onLogin={() => setIsAuthModalOpen(true)} user={user} />
        {isAuthModalOpen && (
          <AuthModal 
            language={language} 
            onClose={() => setIsAuthModalOpen(false)} 
            onLoginSuccess={handleLoginSuccess} 
          />
        )}
      </>
    );
  }

  if (currentView === 'ADMIN') {
    return (
      <>
        <AdminDashboard 
          listings={listings}
          bookings={bookings}
          onAdd={() => setShowAddForm(true)}
          onEdit={(l) => setEditingListing(l)}
          onDelete={handleDeleteListing}
          onUpdateListingStatus={handleUpdateListingStatus}
          onUpdateBookingStatus={handleUpdateBookingStatus}
          onLogout={handleLogout}
          language={language}
        />
        {(showAddForm || editingListing) && (
           <AdminListingForm 
            listing={editingListing}
            onClose={() => { setShowAddForm(false); setEditingListing(null); }} 
            onSubmit={editingListing ? handleUpdateListing : handleAddListing} 
           />
        )}
      </>
    );
  }

  if (currentView === 'OWNER') {
    return (
      <>
        <OwnerDashboard 
          listings={listings}
          onAdd={() => setShowAddForm(true)}
          onLogout={handleLogout}
          isSubscribed={isOwnerSubscribed}
          onSubscribe={() => setIsOwnerSubscribed(true)}
          language={language}
          user={user}
        />
        {showAddForm && (
           <AdminListingForm 
            onClose={() => setShowAddForm(false)} 
            onSubmit={handleAddListing} 
           />
        )}
      </>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <Header 
        onLogout={handleLogout} 
        user={user}
        language={language}
        setLanguage={setLanguage}
      />

      {!isSubscribed ? (
        <SubscriptionGate onSubscribe={() => setIsSubscribed(true)} language={language} mode="CUSTOMER" />
      ) : (
        <main className="max-w-6xl mx-auto px-4 pt-8 pb-12 flex-grow w-full">
          <div className="mb-8">
            <h2 className="text-3xl font-bold text-gray-800 mb-2">
              {language === 'HI' ? 'कवर्धा में कमरे खोजें' : 'Find Rooms in Kawardha'}
            </h2>
            <p className="text-gray-500">
              {language === 'HI' ? 'वेरिफाइड पीजी, फ्लैट और कमरे देखें। विश्वास के साथ सीधे बुकिंग करें।' : 'Browse verified PGs, flats, and rooms. Book directly with confidence.'}
            </p>
          </div>

          <FilterBar filters={filters} setFilters={setFilters} />

          <div className="mb-4 flex items-center justify-between">
            <p className="text-sm text-gray-500">
              {language === 'HI' ? 'कुल ' : 'Showing '} 
              <span className="font-bold text-gray-900">{filteredListings.length}</span> 
              {language === 'HI' ? ' परिणाम मिले' : ' premium results'}
            </p>
          </div>

          {filteredListings.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {filteredListings.map(listing => (
                <ListingCard 
                  key={listing.id} 
                  listing={listing} 
                  isAdmin={false} 
                  onBook={() => setBookingListing(listing)}
                  language={language}
                />
              ))}
            </div>
          ) : (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-16 text-center flex flex-col items-center">
              <div className="bg-gray-50 p-6 rounded-full mb-6">
                <SearchX size={48} className="text-gray-400" />
              </div>
              <h3 className="text-xl font-bold text-gray-800 mb-2">{t.noRooms}</h3>
              <button 
                onClick={() => setFilters({ maxPrice: 10000, roomType: 'ALL', locality: 'ALL' })}
                className="text-orange-600 font-bold hover:underline"
              >
                {t.clearFilters}
              </button>
            </div>
          )}
        </main>
      )}

      <Footer />

      {bookingListing && (
        <BookingModal 
          listing={bookingListing} 
          onClose={() => setBookingListing(null)} 
          onConfirm={handleCreateBooking}
        />
      )}

      {isSubscribed && <AIAssistant />}

      {isAuthModalOpen && (
        <AuthModal 
          language={language} 
          onClose={() => setIsAuthModalOpen(false)} 
          onLoginSuccess={handleLoginSuccess} 
        />
      )}
    </div>
  );
}

export default App;

