              >
                {isLoading ? <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : (language === 'HI' ? 'OTP भेजें' : 'Send Gmail OTP')}
              </button>
              <button type="button" onClick={() => setStep('LOGIN')} className="w-full text-[10px] text-slate-300 font-black uppercase tracking-widest hover:text-slate-500">
                {language === 'HI' ? 'लॉगिन पर वापस' : 'Back to Login'}
              </button>
            </form>
          )}

          {step === 'OTP' && (
            <div className="space-y-8 animate-fade-in text-center">
              <div className="flex justify-between gap-2 max-w-xs mx-auto">
                {otp.map((digit, idx) => (
                  <input
                    key={idx}
                    id={`otp-${idx}`}
                    type="text"
                    maxLength={1}
                    value={digit}
                    onChange={(e) => handleOtpChange(idx, e.target.value)}
                    className="w-12 h-14 text-center text-2xl font-black border-2 border-slate-100 bg-slate-50 rounded-xl focus:border-orange-500 focus:bg-white outline-none transition-all"
                  />
                ))}
              </div>

              <div className="bg-orange-50 p-6 rounded-3xl border border-orange-100">
                <div className="flex justify-center mb-3 text-orange-600">
                   <ShieldCheck size={32} className="animate-pulse" />
                </div>
                <p className="text-xs text-orange-900 font-bold leading-relaxed">
                  {language === 'HI' ? 'हमने आपके Gmail पर 6 अंकों का कोड भेजा है।' : 'We have sent a 6-digit code to your Gmail.'}
                </p>
                <p className="text-[10px] text-orange-400 mt-2 font-black uppercase tracking-widest">
                  Demo Code: 123456
                </p>
              </div>

              <button 
                onClick={handleVerifyOtp}
                disabled={isLoading || otp.some(d => !d)}
                className={`w-full ${accentColor} ${accentHover} text-white py-5 rounded-2xl font-black text-lg transition-all shadow-xl flex items-center justify-center gap-2 transform active:scale-95 disabled:opacity-50`}
              >
                {isLoading ? <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : (language === 'HI' ? 'सत्यापन करें' : 'Verify & Continue')}
              </button>

              <button 
                type="button" 
                onClick={() => setStep('SIGNUP')} 
                className="text-[10px] text-slate-300 font-black uppercase tracking-widest hover:text-slate-500"
              >
                {language === 'HI' ? 'ईमेल बदलें' : 'Change Gmail'}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

