import React, { useState } from 'react';
import { X, Mail, Lock, User, Key, ShieldCheck, UserCheck, Home, Settings } from 'lucide-react';
import { Language, User as UserType, UserRole } from '../types';
import { translations } from '../translations';

interface AuthModalProps {
  onClose: () => void;
  onLoginSuccess: (user: UserType) => void;
  language: Language;
  mode: UserRole;
}

type AuthStep = 'SIGNUP' | 'OTP' | 'LOGIN';

const AuthModal: React.FC<AuthModalProps> = ({ onClose, onLoginSuccess, language, mode }) => {
  const [step, setStep] = useState<AuthStep>('LOGIN');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [isLoading, setIsLoading] = useState(false);

  const t = translations[language];

  // Simulated User Database (for role verification demo)
  const mockDb = [
    { email: 'admin@saathi.com', password: '123', role: 'ADMIN', name: 'Super Admin' },
    { email: 'owner@saathi.com', password: '123', role: 'OWNER', name: 'Rajesh Kumar' },
    { email: 'user@saathi.com', password: '123', role: 'CUSTOMER', name: 'Amit Singh' }
  ];

  const handleSignupSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setStep('OTP');
      const msg = language === 'HI' 
        ? `सफलता! OTP आपके ईमेल ${email} पर भेज दिया गया है। (डेमो के लिए 123456 का उपयोग करें)` 
        : `Success! OTP sent to ${email}. (Use 123456 for demo)`;
      alert(msg);
    }, 1200);
  };

  const handleOtpChange = (index: number, value: string) => {
    if (value.length > 1) return;
    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);
    if (value && index < 5) {
      document.getElementById(`otp-${index + 1}`)?.focus();
    }
  };

  const handleVerifyOtp = () => {
    const enteredOtp = otp.join('');
    if (enteredOtp === '123456') {
      setIsLoading(true);
      setTimeout(() => {
        const newUser: UserType = {
          id: 'user_' + Date.now(),
          name: name || 'User',
          email: email,
          role: mode, // Strictly assigning the role based on the portal they used
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name || 'User'}`
        };
        onLoginSuccess(newUser);
      }, 800);
