  };

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    setTimeout(() => {
      setIsLoading(false);
      // Simulate checking credentials AND role
      const foundUser = mockDb.find(u => u.email === email && u.password === password);

      if (foundUser) {
        if (foundUser.role === mode) {
          const loggedInUser: UserType = {
            id: 'db_' + Math.random(),
            name: foundUser.name,
            email: foundUser.email,
            role: foundUser.role as UserRole,
            avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${foundUser.name}`
          };
          onLoginSuccess(loggedInUser);
        } else {
          // ROLE MISMATCH ERROR
          const errorMsg = language === 'HI' 
            ? `त्रुटि: आप इस ईमेल से ${mode} के रूप में लॉगिन नहीं कर सकते। यह एक ${foundUser.role} खाता है।` 
            : `Error: You cannot log in as ${mode} with this email. This is a ${foundUser.role} account.`;
          alert(errorMsg);
        }
      } else {
        // Just for demo, let them login if not in mockDb but simulate role match
        const dummyUser: UserType = {
          id: 'dummy_' + Date.now(),
          name: email.split('@')[0],
          email: email,
          role: mode,
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${email}`
        };
        onLoginSuccess(dummyUser);
      }
    }, 1000);
  };

  const isCustomer = mode === 'CUSTOMER';
  const isAdmin = mode === 'ADMIN';
  const isOwner = mode === 'OWNER';

  const accentColor = isAdmin ? 'bg-indigo-700' : isOwner ? 'bg-slate-900' : 'bg-orange-600';
  const accentHover = isAdmin ? 'hover:bg-indigo-800' : isOwner ? 'hover:bg-slate-800' : 'hover:bg-orange-700';
  const portalName = isAdmin ? 'Admin' : isOwner ? 'Owner' : 'Customer';

  return (
    <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-in fade-in zoom-in duration-200">
