              <span className="text-[10px] font-black uppercase tracking-[0.2em] bg-white/10 px-3 py-1 rounded-full">
                {portalName} Access
              </span>
            </div>
            <h3 className="text-3xl font-black">
              {step === 'LOGIN' ? (language === 'HI' ? 'लॉगिन' : 'Login') : 
               step === 'SIGNUP' ? (language === 'HI' ? 'साइनअप' : 'Sign up') :
               (language === 'HI' ? 'सत्यापन' : 'OTP Code')}
            </h3>
            <p className="text-white/70 text-xs font-bold mt-2">
              {step === 'OTP' ? email : (language === 'HI' ? `${portalName} पोर्टल में आपका स्वागत है` : `Welcome to the ${portalName} Portal`)}
            </p>
          </div>
          <button onClick={onClose} className="absolute top-6 right-6 bg-white/10 hover:bg-white/20 p-2 rounded-full transition-all">
            <X size={20} />
          </button>
          <div className="absolute -right-12 -bottom-12 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
        </div>

        <div className="p-8">
          {step === 'LOGIN' && (
            <form onSubmit={handleLoginSubmit} className="space-y-5">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Gmail Account</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                  <input 
                    type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 focus:bg-white outline-none transition-all font-bold text-slate-700"
                    placeholder="name@gmail.com"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Password</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                  <input 
                    type="password" required value={password} onChange={(e) => setPassword(e.target.value)}
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 focus:bg-white outline-none transition-all font-bold text-slate-700"
                    placeholder="••••••••"
                  />
                </div>
              </div>
              <button 
                type="submit" disabled={isLoading}
                className={`w-full ${accentColor} ${accentHover} text-white py-5 rounded-2xl font-black text-lg transition-all shadow-xl shadow-indigo-100 flex items-center justify-center gap-2 transform active:scale-95`}
              >
                {isLoading ? <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : (language === 'HI' ? 'लॉगिन' : 'Login')}
              </button>
              <div className="text-center pt-2">
                <p className="text-xs text-slate-400 font-bold">
                  {language === 'HI' ? 'अकाउंट नहीं है?' : "Don't have an account?"} {' '}
                  <button type="button" onClick={() => setStep('SIGNUP')} className="text-indigo-600 font-black hover:underline">
                    {language === 'HI' ? 'यहाँ साइनअप करें' : 'Sign up here'}
                  </button>
                </p>
              </div>
            </form>
          )}

          {step === 'SIGNUP' && (
            <form onSubmit={handleSignupSubmit} className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Username</label>
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                  <input 
                    type="text" required value={name} onChange={(e) => setName(e.target.value)}
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 focus:bg-white outline-none transition-all font-bold text-slate-700"
                    placeholder="Full Name"
                  />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Gmail Address</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                  <input 
                    type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 focus:bg-white outline-none transition-all font-bold text-slate-700"
                    placeholder="you@gmail.com"
                  />
