import React, { useState } from 'react';
import { X, Mail, Lock, User, Key, ShieldCheck, UserCheck, Home, Settings } from 'lucide-react';
import { Language, User as UserType, UserRole } from '../types';
import { translations } from '../translations';

interface AuthModalProps {
  onClose: () => void;
  onLoginSuccess: (user: UserType) => void;
  language: Language;
  mode: UserRole;
}

type AuthStep = 'SIGNUP' | 'OTP' | 'LOGIN';

const AuthModal: React.FC<AuthModalProps> = ({ onClose, onLoginSuccess, language, mode }) => {
  const [step, setStep] = useState<AuthStep>('LOGIN');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [isLoading, setIsLoading] = useState(false);

  const t = translations[language];

  // Simulated Database with Role constraints
  const mockDb = [
    { email: 'admin@saathi.com', password: '123', role: 'ADMIN', name: 'Super Admin' },
    { email: 'owner@saathi.com', password: '123', role: 'OWNER', name: 'Rajesh Owner' },
    { email: 'user@saathi.com', password: '123', role: 'CUSTOMER', name: 'Kawardha User' }
  ];

  const handleSignupSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setStep('OTP');
      alert(language === 'HI' ? `OTP आपके ईमेल पर भेज दिया गया है। (डेमो के लिए 123456 डालें)` : `OTP sent. (Use 123456 for demo)`);
    }, 1500);
  };

  const handleOtpChange = (index: number, value: string) => {
    if (value.length > 1) return;
    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);
    if (value && index < 5) document.getElementById(`otp-${index + 1}`)?.focus();
  };

  const handleVerifyOtp = () => {
    if (otp.join('') === '123456') {
      setIsLoading(true);
      setTimeout(() => {
        onLoginSuccess({
          id: 'user_' + Date.now(),
          name: name || email.split('@')[0],
          email: email,
          role: mode, // Set role permanently based on the portal used
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name || email}`
        });
      }, 1000);
    } else {
      alert(language === 'HI' ? 'गलत OTP!' : 'Incorrect OTP!');
    }
  };

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      const found = mockDb.find(u => u.email === email && u.password === password);

      if (found) {
        // STRICT ROLE CHECK: Compare DB role with current modal mode
        if (found.role === mode) {
          onLoginSuccess({
            id: 'id_' + Math.random(),
            name: found.name,
            email: found.email,
            role: found.role as UserRole,
            avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${found.name}`
          });
        } else {
          // Block cross-portal login
          const errorMsg = language === 'HI' 
            ? `त्रुटि: यह ईमेल एक ${found.role} खाता है। आप यहाँ से लॉगिन नहीं कर सकते।` 
            : `Error: This email is a ${found.role} account. You cannot log in here.`;
          alert(errorMsg);
        }
      } else {
        // For new users not in mockDb, allow demo login but enforce role
        onLoginSuccess({
          id: 'new_' + Date.now(),
          name: email.split('@')[0],
          email: email,
          role: mode,
          avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${email}`
        });
      }
    }, 1000);
  };

  const isCustomer = mode === 'CUSTOMER';
  const isAdmin = mode === 'ADMIN';
  const accentColor = isAdmin ? 'bg-indigo-700' : isCustomer ? 'bg-orange-600' : 'bg-slate-900';
  const portalTitle = isAdmin ? 'Admin' : isCustomer ? 'Tenant' : 'Owner';

  return (
    <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full overflow-hidden">
        <div className={`${accentColor} p-8 text-white relative`}>
          <div className="relative z-10">
            <h3 className="text-2xl font-black mb-1">
              {step === 'LOGIN' ? `${portalTitle} Login` : step === 'SIGNUP' ? 'Join Us' : 'Verify'}
            </h3>
            <p className="text-white/60 text-xs font-bold uppercase tracking-widest">
              {isAdmin ? 'Secure System' : isCustomer ? '₹199 Membership' : '₹49 Listing Fee'}
            </p>
          </div>
          <button onClick={onClose} className="absolute top-6 right-6 p-2 bg-white/10 hover:bg-white/20 rounded-full">
            <X size={20} />
          </button>
        </div>

        <div className="p-8">
          {step === 'LOGIN' && (
            <form onSubmit={handleLoginSubmit} className="space-y-5">
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                <input 
                  type="email" required value={email} onChange={e => setEmail(e.target.value)}
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 outline-none font-bold"
                  placeholder="name@gmail.com"
                />
              </div>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                <input 
                  type="password" required value={password} onChange={e => setPassword(e.target.value)}
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-orange-500 outline-none font-bold"
                  placeholder="Password"
                />
              </div>
              <button type="submit" className={`w-full ${accentColor} text-white py-5 rounded-2xl font-black text-lg shadow-xl`}>
                {isLoading ? '...' : (language === 'HI' ? 'लॉगिन' : 'Login')}
              </button>
              <p className="text-center text-xs font-bold text-slate-400">
                New? <button type="button" onClick={() => setStep('SIGNUP')} className="text-orange-600 hover:underline">Create Account</button>
              </p>
            </form>
          )}

          {step === 'SIGNUP' && (
            <form onSubmit={handleSignupSubmit} className="space-y-4">
              <input type="text" required value={name} onChange={e => setName(e.target.value)} placeholder="Full Name" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold" />
              <input type="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="Gmail Address" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold" />
              <input type="password" required value={password} onChange={e => setPassword(e.target.value)} placeholder="Create Password" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold" />
              <button type="submit" className={`w-full ${accentColor} text-white py-5 rounded-2xl font-black text-lg shadow-xl`}>
                {language === 'HI' ? 'OTP भेजें' : 'Send Gmail OTP'}
              </button>
              <button type="button" onClick={() => setStep('LOGIN')} className="w-full text-center text-xs text-slate-400 font-bold uppercase tracking-widest">Back to Login</button>
            </form>
          )}

          {step === 'OTP' && (
            <div className="space-y-8 text-center">
              <div className="flex justify-between gap-2 max-w-xs mx-auto">
                {otp.map((d, i) => (
                  <input key={i} id={`otp-${i}`} type="text" maxLength={1} value={d} onChange={e => handleOtpChange(i, e.target.value)} className="w-12 h-14 text-center text-2xl font-black border-2 border-slate-100 bg-slate-50 rounded-xl focus:border-orange-500 outline-none" />
                ))}
              </div>
              <p className="text-xs text-slate-500 font-bold">Code: 123456</p>
              <button onClick={handleVerifyOtp} className={`w-full ${accentColor} text-white py-5 rounded-2xl font-black text-lg shadow-xl`}>Verify</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

